ROOT=Path(__file__).resolve().parents[2];OUT=ROOT/'results/E7d_park_warp/2026-10-28/white_pointmaps';z=np.load(OUT/'pointmap_candidates.npz');a=z['source_xyz'];b=z['target_xyz'];fold=z['fold'];center=b.mean(0);_,_,v=np.linalg.svd(b-center,full_matrices=False);n=v[-1];n=n if n[2]>=0 else -n;diff=np.empty_like(a)
